<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Catalog\DTO\Request\UploadSyllabusDocumentRequestDto;use App\Application\Catalog\Port\SyllabusDocumentStorageInterface;use App\Application\Catalog\Port\TransactionManagerInterface;use App\Domain\Catalog\Entity\Syllabus;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;
final class UploadSyllabusDocumentService { public function __construct(private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusDocumentStorageInterface $storage,private readonly TransactionManagerInterface $transactions){} public function upload(UploadSyllabusDocumentRequestDto $input):Syllabus{return $this->transactions->transactional(function()use($input){if($input->mimeType!=='application/pdf'||!str_starts_with($input->contents,'%PDF-'))throw new \InvalidArgumentException('Informe um PDF valido.');$syllabus=$this->syllabi->findById($input->syllabusId);if($syllabus===null)throw new \DomainException('Edital nao encontrado.');$hash=hash('sha256',$input->contents);$path=$this->storage->store($hash,$input->originalName,$input->contents);$updated=new Syllabus($syllabus->id,$syllabus->examId,$syllabus->name,$syllabus->publishedAt,$syllabus->sourceUrl,$path,$hash,$input->originalName,$input->mimeType,strlen($input->contents));$this->syllabi->save($updated);return $updated;});} }
